manifest=json.loads(manifest_path.read_text(encoding='utf-8'))
if 'combat-facade' in manifest['loadOrder']: raise SystemExit('combat-facade already exists in module manifest')
pos=manifest['loadOrder'].index('combat-mana-action-resolution')+1
manifest['loadOrder'].insert(pos,'combat-facade')
facade_module={
  'id':'combat-facade','path':'js/combat/facade.js','domain':'combat/public-engine-facade','status':'extracted',
  'requires':['combat-healing-resolution','combat-element-resolution','combat-d20-chaos-resolution','combat-strike-resolution','combat-attack-action-resolution','combat-ultimate-resolution','combat-guard-resolution','combat-pet-turn-resolution','combat-victory-resolution','combat-enemy-scaling-resolution','combat-encounter-lifecycle','combat-turn-resolution','combat-mana-action-resolution'],
  'provides':['DiceboundCombat']
}
module_pos=next(i for i,m in enumerate(manifest['modules']) if m['id']=='combat-mana-action-resolution')+1
manifest['modules'].insert(module_pos,facade_module)
manifest_path.write_text(json.dumps(manifest,indent=2)+'\n',encoding='utf-8')

project=json.loads(project_path.read_text(encoding='utf-8'))
script='js/combat/facade.js'
if script in project['runtimeScripts']: raise SystemExit('Combat facade already exists in project runtimeScripts')
